// General power-of-2 base conversion, as `bech32.convertbits`.

/**
 * Regroup `data` from `frombits`-wide symbols into `tobits`-wide ones.
 *
 * Returns `null` (Python's `None`) when a symbol does not fit in `frombits` --
 * which is what makes `convertbits(witprog, 5, 8)` fail for any witness program
 * byte >= 32 -- and, when `pad` is false, when the trailing partial group is
 * either too wide or not all zeroes.
 */
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const maxAcc = (1 << (frombits + tobits - 1)) - 1;

  for (const value of data) {
    if (value < 0 || value >> frombits) {
      return null;
    }
    acc = ((acc << frombits) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }

  if (pad) {
    if (bits) {
      ret.push((acc << (tobits - bits)) & maxv);
    }
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
    return null;
  }
  return ret;
}
