/** `--flag` -> dest `flag`; argparse also maps inner dashes to underscores. */
export function destFromOptionStrings(optionStrings) {
  const long = optionStrings.find((option) => option.startsWith('--'));
  const chosen = long === undefined ? optionStrings[0] : long;
  return chosen.replace(/^-+/, '').replace(/-/g, '_');
}

export function makeHelpAction() {
  return new Action({
    optionStrings: ['-h', '--help'],
    dest: 'help',
    kind: HELP,
    nargs: 0,
    help: 'show this help message and exit',
  });
}
