// Usage and help rendering, reproducing argparse's HelpFormatter layout.

const INDENT = 2;
const MAX_HELP_POSITION = 24;

/** `-h, --help` for a flag, `--a A` for an option that takes a value. */
export function formatInvocation(action) {
  const joined = action.optionStrings.join(', ');
  return action.nargs === 0 ? joined : `${joined} ${action.metavar}`;
}

/** The bracketed form used in the usage line, built from the first option only. */
function formatUsagePart(action) {
  const option = action.optionStrings[0];
  const part = action.nargs === 0 ? option : `${option} ${action.metavar}`;
  return action.required ? part : `[${part}]`;
}

export function formatUsage(prog, actions) {
  const parts = actions.map(formatUsagePart);
  const tail = parts.length === 0 ? '' : ` ${parts.join(' ')}`;
  return `usage: ${prog}${tail}\n`;
}

export function formatHelp(prog, actions) {
  const invocations = actions.map(formatInvocation);
  const actionMaxLength = Math.max(0, ...invocations.map((text) => text.length + INDENT));
  const helpPosition = Math.min(actionMaxLength + 2, MAX_HELP_POSITION);
  const actionWidth = helpPosition - INDENT - 2;

  const pad = ' '.repeat(INDENT);
  const lines = [formatUsage(prog, actions), '\n', 'options:\n'];

  actions.forEach((action, index) => {
    const invocation = invocations[index];
    if (!action.help) {
      // No help text: the invocation stands alone, with no trailing padding.
      lines.push(`${pad}${invocation}\n`);
    } else if (invocation.length <= actionWidth) {
      lines.push(`${pad}${invocation.padEnd(actionWidth)}  ${action.help}\n`);
    } else {
      // Too wide to share a line, so the help text starts on the next one.
      lines.push(`${pad}${invocation}\n`);
      lines.push(`${' '.repeat(helpPosition)}${action.help}\n`);
    }
  });

  return `${lines.join('').replace(/\n+$/, '')}\n`;
}
