// Corpus generator for family: v1-v16-valid
// Valid segwit addresses with witness versions 1..16 and program lengths 2..40,
// plus the surrounding boundaries (proglen 1/41+, witver 17..31, the 31/32
// byte-value boundary that flips convertbits(witprog,5,8) between list and None,
// the pad=false trailing-group rules, HRP shapes and case handling).
import { mkdirSync, writeFileSync } from 'node:fs';
import { segwitEncode, bech32Encode, convertbits } from '/tmp/probe/gen.mjs';

const cases = [];
const seen = new Set();
function add(hrp, addr) {
  if (addr === null || addr === undefined) return;
  const key = `${hrp}�${addr}`;
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(['--a', hrp, '--b', addr]);
}
/** raw bech32 from 5-bit data symbols (bypasses the 8->5 padding rules) */
function raw(hrp, data) {
  add(hrp, bech32Encode(hrp, data));
}
function seg(hrp, witver, prog) {
  add(hrp, segwitEncode(hrp, witver, prog));
}

const WITVERS = [];
for (let v = 1; v <= 16; v += 1) WITVERS.push(v);

// ---------------------------------------------------------------- A. main sweep
// Every witness version 1..16 x every program length 2..40, in two flavours:
//   "lo" - all bytes <= 31, so convertbits(witprog,5,8) yields a list
//   "hi" - one byte == 32, so convertbits returns None
for (const v of WITVERS) {
  for (let n = 2; n <= 40; n += 1) {
    const lo = [];
    for (let i = 0; i < n; i += 1) lo.push(31 - (i % 32)); // starts at the 31 boundary
    seg('bc', v, lo);

    const hi = lo.slice();
    hi[n % 2 === 0 ? n - 1 : 0] = 32; // just over the boundary
    seg('bc', v, hi);
  }
}

// -------------------------------------------------- B. byte-value boundary grid
const B_LENS = [2, 3, 4, 5, 19, 20, 21, 31, 32, 33, 39, 40];
for (const v of [1, 2, 16]) {
  for (const n of B_LENS) {
    for (const byte of [0, 30, 31, 32, 33, 255]) {
      seg('bc', v, new Array(n).fill(byte));
    }
  }
}
// a single boundary byte hidden at the head / tail of an otherwise-zero program
for (const v of [1, 8, 16]) {
  for (const n of [2, 20, 32, 40]) {
    for (const byte of [31, 32]) {
      for (const pos of [0, n - 1]) {
        const prog = new Array(n).fill(0);
        prog[pos] = byte;
        seg('bc', v, prog);
      }
    }
  }
}

// ------------------------------------------------ C. program-length boundaries
for (const v of WITVERS) {
  for (const n of [1, 41]) {
    seg('bc', v, new Array(n).fill(1));
    seg('bc', v, new Array(n).fill(32));
  }
}
for (const n of [0, 1, 41, 42, 43, 50, 64]) {
  seg('bc', 1, new Array(n).fill(7));
  seg('bc', 16, new Array(n).fill(7));
}

// ------------------------------------------- D. witness version out of range
for (let v = 17; v <= 31; v += 1) {
  for (const n of [2, 20, 32, 40]) {
    const prog = [];
    for (let i = 0; i < n; i += 1) prog.push(31 - (i % 32));
    seg('bc', v, prog);
  }
}

// ------------------------------- E. 5-bit payload sweep (pad=false boundaries)
// data = [witver] + m payload symbols. Accepted only when 5*m % 8 < 5, the
// trailing bits are zero and floor(5*m/8) is in 2..40.
for (const v of [1, 2, 16]) {
  for (let m = 0; m <= 66; m += 1) {
    const zeros = new Array(m).fill(0);
    raw('bc', [v, ...zeros]);
    if (m > 0) {
      const dirty = zeros.slice();
      dirty[m - 1] = 1; // low bit set -> non-zero padding when leftover > 0
      raw('bc', [v, ...dirty]);
      const high = zeros.slice();
      high[m - 1] = 16; // high bit of the last symbol
      raw('bc', [v, ...high]);
    }
  }
