const LONG83 = 'a'.repeat(83);
const LONG84 = 'a'.repeat(84);
const LONG82 = 'a'.repeat(82);
const HRPS = ['bc', 'tb', 'bcrt', 'a', 'z', '~', '!', '1', 'b1c', 'bc1', '123', '-', '=',
  'a'.repeat(20), LONG82, LONG83, LONG84];
