for (const v of [1, 5, 16]) {
  for (const n of [2, 20, 40]) {
    const prog = [];
    for (let i = 0; i < n; i += 1) prog.push(31 - (i % 32));
    const addr = segwitEncode('bc', v, prog);
    add('bc', addr.toUpperCase()); // all-upper address, lower hrp arg -> works
    add('BC', addr.toUpperCase()); // hrpgot is lowered -> mismatch
    add('BC', addr); // mismatch
    add('bc', 'bc1' + addr.slice(3).toUpperCase()); // mixed case
    add('bc', addr.slice(0, -1) + addr.slice(-1).toUpperCase()); // one upper char
    add('Bc', addr);
    // digit-only hrp: upper()==s so an all-caps form is not "mixed case"
    const num = segwitEncode('123', v, prog);
    add('123', num.toUpperCase());
    add('123', num);
  }
}

