{
  const prog = [];
  for (let i = 0; i < 20; i += 1) prog.push(31 - (i % 32));
  for (const v of [1, 16]) {
    const addr = segwitEncode('bc', v, prog);
    add('bc', addr);
    add('bc', addr.slice(0, -1) + (addr.slice(-1) === 'q' ? 'p' : 'q')); // bad checksum
    add('bc', addr.slice(0, 3) + (addr[3] === 'q' ? 'p' : 'q') + addr.slice(4)); // bad payload
    add('bc', addr + 'q'); // extra symbol
    add('bc', addr.slice(0, -1)); // truncated
