  add('bc', 'bc1p0xlxvlhemja6c4dqv22uapctqupfhlxm9h8z3k2e72q4k9hcz7vqzk5jj0');
  add('bc', 'bc1pw508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7kt5nd6y');
  add('bc', 'bc1zw508d6qejxtdg4y5r3zarvaryvg6kdaj'); // v2, ordinary checksum -> 2
  add('bc', 'bc1sw50qa3jx3s'); // v16
  add('bc', 'bc1pqypqj3p230');
  add('bc', 'bc1sru0s6wgyhl');
  add('bc', 'bc19qypqxpq9vu00uz');
  add('bc', 'bc1zqypqxe7v2x0');
  add('bc', 'bc1pw508d6qejxtdg4y5r3zarvary0c5xw7kw508d6qejxtdg4y5r3zarvary0c5xw7k7grplx');
