{
  const prog40 = [];
  for (let i = 0; i < 40; i += 1) prog40.push(i % 32);
  for (const hrp of [LONG82, LONG83, LONG84]) {
    seg(hrp, 1, prog40);
    seg(hrp, 16, prog40);
    const a = segwitEncode(hrp, 1, prog40);
    add(hrp, a.toUpperCase());
  }
}

