// pair produces both a list-printing case and a None-printing case in the corpus.
import { spawn } from 'node:child_process';
import { segwitEncode } from '/tmp/probe/gen.mjs';

const EXE = '/workspace/dataset/test12_executable';
function run(argv) {
  return new Promise((resolve) => {
    const c = spawn(EXE, argv, { stdio: ['ignore', 'pipe', 'pipe'] });
    let out = '';
    c.stdout.setEncoding('utf8');
    c.stdout.on('data', (d) => { out += d; });
    c.on('close', () => resolve(out));
  });
}

const jobs = [];
for (let v = 1; v <= 16; v += 1) {
  for (let n = 2; n <= 40; n += 1) {
    const lo = [];
    for (let i = 0; i < n; i += 1) lo.push(31 - (i % 32));
    const hi = lo.slice();
    hi[n % 2 === 0 ? n - 1 : 0] = 32;
    jobs.push({ v, n, kind: 'lo', addr: segwitEncode('bc', v, lo) });
    jobs.push({ v, n, kind: 'hi', addr: segwitEncode('bc', v, hi) });
  }
}

let next = 0;
const bad = [];
let listPaths = 0;
let nonePaths = 0;
async function worker() {
  for (;;) {
    const i = next; next += 1;
    if (i >= jobs.length) return;
    const j = jobs[i];
    const out = await run(['--a', 'bc', '--b', j.addr]);
    const lines = out.split('\n');
    const okVer = lines[0] === String(j.v);
    const isNone = lines[1] === 'None';
    const isList = lines[1] !== undefined && lines[1].startsWith('[');
    if (isNone) nonePaths += 1;
    if (isList) listPaths += 1;
    if (!okVer || (j.kind === 'lo' && !isList) || (j.kind === 'hi' && !isNone)) {
      bad.push({ ...j, out });
    }
  }
}
await Promise.all(Array.from({ length: 28 }, worker));
console.log(`pairs=${jobs.length / 2} listPaths=${listPaths} nonePaths=${nonePaths} unexpected=${bad.length}`);
for (const b of bad.slice(0, 5)) console.log(JSON.stringify(b));

